function predictWeak(sample, stump) {
  const val = stump.axis === 'x' ? sample.x : sample.y;
  if (stump.op === '<=') {
    return val <= stump.thr ? 1 : -1;
  } else {
    return val >= stump.thr ? 1 : -1;
  }
}
